CREATE TYPE "EventStatus" AS ENUM ('DRAFT', 'PUBLISHED', 'CLOSED', 'CANCELLED');
CREATE TYPE "ExceptionMode" AS ENUM ('INCLUDE', 'EXCLUDE');
CREATE TYPE "DocumentType" AS ENUM ('GUARDIAN_IDENTITY', 'EXTERNAL_IDENTITY');
CREATE TYPE "SubmissionStatus" AS ENUM ('RECEIVED', 'PROCESSED');
CREATE TYPE "AuthorizationStatus" AS ENUM ('SIGNED', 'ANNULLED');

CREATE TABLE "user" ("id" UUID PRIMARY KEY, "email" TEXT UNIQUE, "phone_e164" TEXT UNIQUE, "first_name" TEXT NOT NULL, "paternal_surname" TEXT NOT NULL, "maternal_surname" TEXT, "is_admin" BOOLEAN NOT NULL DEFAULT false, "is_active" BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE "session" ("id" UUID PRIMARY KEY, "user_id" UUID NOT NULL REFERENCES "user"("id") ON DELETE RESTRICT ON UPDATE CASCADE, "token_hash" TEXT NOT NULL UNIQUE, "expires_at" TIMESTAMPTZ NOT NULL, "revoked_at" TIMESTAMPTZ, "ip" TEXT, "user_agent" TEXT);
CREATE TABLE "course" ("id" UUID PRIMARY KEY, "name" TEXT NOT NULL, "level" TEXT NOT NULL, "year" INTEGER NOT NULL, "is_active" BOOLEAN NOT NULL DEFAULT true, UNIQUE("name", "year"));
CREATE TABLE "student" ("id" UUID PRIMARY KEY, "document_type" TEXT NOT NULL, "document_number" TEXT NOT NULL UNIQUE, "first_name" TEXT NOT NULL, "paternal_surname" TEXT NOT NULL, "maternal_surname" TEXT, "course_id" UUID NOT NULL REFERENCES "course"("id") ON DELETE RESTRICT ON UPDATE CASCADE, "is_active" BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE "guardian_student" ("id" UUID PRIMARY KEY, "guardian_id" UUID NOT NULL REFERENCES "user"("id") ON DELETE RESTRICT ON UPDATE CASCADE, "student_id" UUID NOT NULL REFERENCES "student"("id") ON DELETE RESTRICT ON UPDATE CASCADE, "relationship" TEXT NOT NULL, "is_primary" BOOLEAN NOT NULL DEFAULT false, UNIQUE("guardian_id", "student_id"));
CREATE TABLE "event" ("id" UUID PRIMARY KEY, "type" TEXT NOT NULL, "title" TEXT NOT NULL, "description" TEXT NOT NULL, "location" TEXT, "starts_at" TIMESTAMPTZ NOT NULL, "ends_at" TIMESTAMPTZ NOT NULL, "authorization_text" TEXT NOT NULL, "deadline_at" TIMESTAMPTZ NOT NULL, "status" "EventStatus" NOT NULL DEFAULT 'DRAFT', "created_by_id" UUID NOT NULL REFERENCES "user"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "event_course" ("id" UUID PRIMARY KEY, "event_id" UUID NOT NULL REFERENCES "event"("id") ON DELETE CASCADE ON UPDATE CASCADE, "course_id" UUID NOT NULL REFERENCES "course"("id") ON DELETE RESTRICT ON UPDATE CASCADE, UNIQUE("event_id", "course_id"));
CREATE TABLE "event_student_exception" ("id" UUID PRIMARY KEY, "event_id" UUID NOT NULL REFERENCES "event"("id") ON DELETE CASCADE ON UPDATE CASCADE, "student_id" UUID NOT NULL REFERENCES "student"("id") ON DELETE RESTRICT ON UPDATE CASCADE, "mode" "ExceptionMode" NOT NULL, UNIQUE("event_id", "student_id"));
CREATE TABLE "document" ("id" UUID PRIMARY KEY, "owner_id" UUID REFERENCES "user"("id") ON DELETE SET NULL ON UPDATE CASCADE, "type" "DocumentType" NOT NULL, "private_path" TEXT NOT NULL, "mime_type" TEXT NOT NULL, "size_bytes" INTEGER NOT NULL, "sha256" TEXT NOT NULL, "is_encrypted" BOOLEAN NOT NULL DEFAULT false, "is_simulated" BOOLEAN NOT NULL DEFAULT false, "delete_after" TIMESTAMPTZ NOT NULL, "deleted_at" TIMESTAMPTZ, "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "authorization_submission" ("id" UUID PRIMARY KEY, "guardian_id" UUID NOT NULL REFERENCES "user"("id") ON DELETE RESTRICT ON UPDATE CASCADE, "document_id" UUID UNIQUE REFERENCES "document"("id") ON DELETE SET NULL ON UPDATE CASCADE, "idempotency_key" UUID NOT NULL, "ip" TEXT, "user_agent" TEXT, "session_id" UUID NOT NULL REFERENCES "session"("id") ON DELETE RESTRICT ON UPDATE CASCADE, "status" "SubmissionStatus" NOT NULL DEFAULT 'RECEIVED', "result_snapshot" JSONB, "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("guardian_id", "idempotency_key"));
CREATE TABLE "authorization" ("id" UUID PRIMARY KEY, "event_id" UUID NOT NULL REFERENCES "event"("id") ON DELETE RESTRICT ON UPDATE CASCADE, "student_id" UUID NOT NULL REFERENCES "student"("id") ON DELETE RESTRICT ON UPDATE CASCADE, "guardian_id" UUID NOT NULL REFERENCES "user"("id") ON DELETE RESTRICT ON UPDATE CASCADE, "submission_id" UUID NOT NULL REFERENCES "authorization_submission"("id") ON DELETE RESTRICT ON UPDATE CASCADE, "document_id" UUID NOT NULL REFERENCES "document"("id") ON DELETE RESTRICT ON UPDATE CASCADE, "status" "AuthorizationStatus" NOT NULL DEFAULT 'SIGNED', "signed_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "ip" TEXT, "user_agent" TEXT, "session_id" UUID NOT NULL REFERENCES "session"("id") ON DELETE RESTRICT ON UPDATE CASCADE, "authorization_text_snapshot" TEXT NOT NULL, "authorization_text_hash" TEXT NOT NULL, "summary_snapshot" JSONB NOT NULL, "annulled_at" TIMESTAMPTZ, "annulled_by_id" UUID REFERENCES "user"("id") ON DELETE SET NULL ON UPDATE CASCADE, "annulment_reason" TEXT);
CREATE TABLE "audit_log" ("id" UUID PRIMARY KEY, "actor_id" UUID REFERENCES "user"("id") ON DELETE SET NULL ON UPDATE CASCADE, "action" TEXT NOT NULL, "entity" TEXT NOT NULL, "entity_id" UUID NOT NULL, "metadata" JSONB NOT NULL DEFAULT '{}', "ip" TEXT, "user_agent" TEXT, "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE INDEX "session_user_id_expires_at_idx" ON "session"("user_id", "expires_at");
CREATE INDEX "student_course_id_is_active_idx" ON "student"("course_id", "is_active");
CREATE INDEX "guardian_student_student_id_idx" ON "guardian_student"("student_id");
CREATE INDEX "event_status_starts_at_idx" ON "event"("status", "starts_at");
CREATE INDEX "event_deadline_at_idx" ON "event"("deadline_at");
CREATE INDEX "authorization_submission_id_idx" ON "authorization"("submission_id");
CREATE INDEX "authorization_guardian_id_status_idx" ON "authorization"("guardian_id", "status");
CREATE INDEX "authorization_event_id_status_idx" ON "authorization"("event_id", "status");
CREATE INDEX "audit_log_entity_entity_id_idx" ON "audit_log"("entity", "entity_id");
CREATE INDEX "event_student_exception_event_id_student_id_idx" ON "event_student_exception"("event_id", "student_id");
CREATE UNIQUE INDEX "authorization_one_signed_per_pair" ON "authorization"("event_id", "student_id") WHERE "status" = 'SIGNED';
